CREATE TABLE IF NOT EXISTS bp_user (id varchar(255) primary key not null, name varchar(255) not null, icon varchar(800) null, gender varchar(255) null, age int null, create_time datetime not null default CURRENT_TIMESTAMP, modify_time datetime not null default CURRENT_TIMESTAMP, synced integer not null default 0);
CREATE TABLE IF NOT EXISTS bp_version (id integer primary key autoincrement, version varchar(255) not null);
CREATE TABLE IF NOT EXISTS bp (id integer primary key autoincrement, user_id varchar(255) not null, date datetime not null, sys integer not null, dia integer not null, pul integer, feel varchar(255), location varchar(255), posture varchar(255), mark varchar(800), log_date datetime not null, weight FLOAT, UNIQUE(user_id, date));
